SELECT COUNT(*) FROM prop_stock_movement WHERE sku_id=#{movementQueryDTO.skuId}
 AND source_type=#{movementQueryDTO.sourceType}
 AND movement_type=#{movementQueryDTO.movementType}
 AND created_at>=#{movementQueryDTO.start}
 AND created_at<#{movementQueryDTO.end}

SELECT id, after_quantity, after_stock_snapshot_json, before_quantity, before_stock_snapshot_json, created_at, movement_type, operator_role, operator_user_id, quantity, related_arbitration_id, related_audit_id, related_order_id, related_reservation_id, remark, source_type FROM prop_stock_movement WHERE sku_id=#{movementQueryDTO.skuId}
 AND source_type=#{movementQueryDTO.sourceType}
 AND movement_type=#{movementQueryDTO.movementType}
 AND created_at>=#{movementQueryDTO.start}
 AND created_at<#{movementQueryDTO.end}
 ORDER BY created_at DESC,id DESC LIMIT #{movementQueryDTO.limit} OFFSET #{movementQueryDTO.offset}
